if (targetClassName && targetClassName.length >= 3) {
	const classNode = vectorNodes.find((n) => {
		const qn = (n.qualifiedName || "").toLowerCase();
		return (
			qn === targetClassName ||
			qn.endsWith(`.${targetClassName}`) ||
			qn.endsWith(`::${targetClassName}`)
		);
	});
	if (classNode) return classNode;
}
